content='''def transform(grid):
    # Detect each rectangular frame color and fill its interior with scattered color.
    R,C=len(grid),len(grid[0])
    out=[[0]*C for _ in range(R)]
    seen=set()
    for r in range(R):
      for c in range(C):
        color=grid[r][c]
        if not color or (r,c) in seen: continue
        # same-color connected components
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<R and 0<=xx<C and grid[yy][xx]==color and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
        ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
        t,b,l,h=min(ys),max(ys),min(xs),max(xs)
        # solid hollow rectangular outlines, dimensions >= 3
        if len(comp)==2*((b-t+1)+(h-l+1))-4 and b-t>=2 and h-l>=2:
          # choose nonzero specks inside; these are pattern seed and should be removed
          specks=[(y,x,grid[y][x]) for y in range(t+1,b) for x in range(l+1,h) if grid[y][x]!=0 and grid[y][x]!=color]
          other=next((v for y,x,v in specks),0)
          for y in range(t,b+1):
            for x in range(l,h+1):
              if y in (t,b) or x in (l,h): out[y][x]=color
          if other:
            # tile seed pattern, expanding its implied alternating checker/stripe pattern
            for y in range(t+1,b):
              for x in range(l+1,h):
                # pattern based on parity of seed location within interior
                out[y][x]=other if (y-(t+1)+x-(l+1))%2==0 else 0
    return out
'''
